param([Parameter(Mandatory)][string]$Inventory)
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot 'preflight.ps1');. (Join-Path $PSScriptRoot 'runner-lib.ps1');. (Join-Path $PSScriptRoot 'command-dispatch.ps1')
if(-not ('PfProcessBridge' -as [type])){Add-Type -Path (Join-Path $PSScriptRoot 'BoundedProcess.cs')}
$root=(Resolve-Path (Join-Path $PSScriptRoot '..\..\..')).Path;$inventoryPath=(Resolve-Path -LiteralPath $Inventory).Path;$scratch=Join-Path ([IO.Path]::GetTempPath()) ('pf-mvp10-surface-'+[guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($scratch)|Out-Null
$fakePsql=Join-Path $scratch 'psql spy.exe';$credential=Join-Path $scratch 'pg pass';Set-Content -LiteralPath $fakePsql -Value 'not executed';Set-Content -LiteralPath $credential -Value 'not read'
$pwsh=(Get-Process -Id $PID).Path;$hash={param($path)(Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToLowerInvariant()};$manifestHash=& $hash $inventoryPath
$firstMigration=(Resolve-Path -LiteralPath (Join-Path $root 'supabase/migrations/20261003000000_foundation_v1.sql')).Path
$relativeInventory=[IO.Path]::GetRelativePath($root,$inventoryPath).Replace('\','/');$scenarios=@('acl-overloads','operator-provenance','tenant-branch','entitlement-decisions','canonical-retries','financial-inventory','expired-replay','evidence-rollback','bounded-concurrency');$commands=@('runtime-preflight','apply-migrations','acceptance-assertions','concurrency','fixture-cleanup')
function New-Authorization([string]$evidenceRoot){return [ordered]@{status='AUTHORIZED';scope='PF_MVP_10_DISPOSABLE_ACCEPTANCE';authorizationId='OWNER-SYNTHETIC-LOCAL-ONLY';expiresAt=[DateTimeOffset]::UtcNow.AddHours(1).ToString('O');target=[ordered]@{host='not-accessed.invalid';port=5432;database='not_accessed';user='not_accessed';sslMode='require';systemIdentifier='123456789';databaseOid=42;marker='local-only'};psql=[ordered]@{path=$fakePsql;sha256=(& $hash $fakePsql)};powerShell=[ordered]@{path=$pwsh;sha256=(& $hash $pwsh);edition='Core';minimumVersion='7.4.0';maximumExclusiveVersion='8.0.0'};credentialFile=$credential;evidenceDirectory=$evidenceRoot;packageManifest=$relativeInventory;packageManifestSha256=$manifestHash;allowedCommands=$commands;allowedScenarios=$scenarios;permissions=[ordered]@{migrationApply=$true;fixtureWrite=$true;concurrency=$true;fixtureCleanup=$true;environmentDestruction=$false};runtime=[ordered]@{postgresMajor=17;supabaseCompatible=$true;requiredSchemas=@('public','auth','extensions');requiredRoles=@('anon','authenticated','service_role');requiredExtensions=@('pgcrypto');requiredAuthFunctions=@('auth.uid()','auth.jwt()')}}}
function Save-Authorization($authorization,[string]$name){$path=Join-Path $scratch ($name+'.json');$authorization|ConvertTo-Json -Depth 20|Set-Content -LiteralPath $path -Encoding utf8;return $path}
function New-ProcessResult([string]$stdout='', [string]$stderr='',[int]$exitCode=0){$result=[PfProcessResult]::new();$result.ExitCode=$exitCode;$result.StdOut=$stdout;$result.StdErr=$stderr;$result.AllStopped=$true;return $result}
function Enqueue-Frame($spy,[string]$frame=''){ $spy.Results.Enqueue((New-ProcessResult $frame)) }
function Get-RepresentativeSqlFrame([string]$name){
 $source=Get-Content -Raw -LiteralPath (Join-Path $PSScriptRoot ('sql/'+$name));if($name -eq '00_runtime_compatibility.sql'){if($source -notmatch "PF_PASS\|runtime\|'\|\|current_setting\('server_version_num'\)\|\|'\|target-verified"){throw 'runtime source contract changed'};return 'PF_PASS|runtime|170000|target-verified'}
 $matches=[regex]::Matches($source,"'(PF_(?:PASS|RESULT|COUNT)\|[A-Za-z0-9_.:=;|-]+)'");if($matches.Count -ne 1){throw "representative SQL frame is not singular: $name"};return $matches[0].Groups[1].Value
}
function Enqueue-Command($spy,[string]$command){
 if($command -eq 'runtime-preflight'){Enqueue-Frame $spy (Get-RepresentativeSqlFrame '00_runtime_compatibility.sql')}
 elseif($command -eq 'apply-migrations'){Enqueue-Frame $spy (Get-RepresentativeSqlFrame '00_runtime_compatibility.sql');Enqueue-Frame $spy (Get-RepresentativeSqlFrame '01_empty_target.sql');$first=$true;1..41|ForEach-Object{if($first){$spy.Results.Enqueue((New-ProcessResult '' "psql:$firstMigration`:10: NOTICE: extension `"pgcrypto`" already exists, skipping"));$first=$false}else{Enqueue-Frame $spy}};Enqueue-Frame $spy (Get-RepresentativeSqlFrame '02_package_state.sql')}
 elseif($command -eq 'acceptance-assertions'){foreach($name in @('00_runtime_compatibility.sql','02_package_state.sql','10_acl_and_contracts.sql','15_api_role_rls.sql','20_transactional_scenarios.sql','25_financial_refund.sql')){Enqueue-Frame $spy (Get-RepresentativeSqlFrame $name)}}
 elseif($command -eq 'fixture-cleanup'){foreach($name in @('00_runtime_compatibility.sql','02_package_state.sql','90_cleanup.sql')){Enqueue-Frame $spy (Get-RepresentativeSqlFrame $name)}}
}
$spy=[PfSpyProcessAdapter]::new();[PfProcessBridge]::Adapter=$spy;$passed=0
try{
 $authorization=New-Authorization (Join-Path $scratch 'evidence');$authorizationFile=Save-Authorization $authorization 'authorized'
 foreach($command in $commands){Enqueue-Command $spy $command;$preflight=Assert-PfMvp10Preflight $authorizationFile $inventoryPath $command;$global:LASTEXITCODE=if($command -eq 'concurrency'){91}else{$null};$result=Invoke-PfMvp10Command -Preflight $preflight -Command $command -ConcurrencyInvoker {param($p,$e)[pscustomobject]@{Success=$true;Frame='PF_PASS|bounded-concurrency|distinct-backends=2|production-blocker=proven'}};if($result.Success -ne $true -or $result.Command -cne $command){throw "command failed: $command"};$passed++}
 foreach($case in @(@('apply-migrations','migrationApply'),@('acceptance-assertions','fixtureWrite'),@('concurrency','concurrency'),@('concurrency','fixtureWrite'),@('fixture-cleanup','fixtureCleanup'))){$denied=New-Authorization (Join-Path $scratch ('denied-'+$case[0]+'-'+$case[1]));$denied.permissions[$case[1]]=$false;$file=Save-Authorization $denied ([guid]::NewGuid().ToString('N'));$before=$spy.Invocations.Count;$failed=$false;try{Assert-PfMvp10Preflight $file $inventoryPath $case[0]|Out-Null}catch{$failed=$_.Exception.Message -match 'permission absent'};if(-not $failed -or $spy.Invocations.Count -ne $before){throw 'missing permission reached executor'};$passed++}
 $incomplete=Join-Path $scratch 'incomplete.sha256';(Get-Content -LiteralPath $inventoryPath|Select-Object -Skip 1)|Set-Content -LiteralPath $incomplete;$badInventory=New-Authorization (Join-Path $scratch 'incomplete-evidence');$badInventory.packageManifest=[IO.Path]::GetRelativePath($root,$incomplete).Replace('\','/');$badInventory.packageManifestSha256=& $hash $incomplete;$badFile=Save-Authorization $badInventory 'incomplete';$before=$spy.Invocations.Count;$failed=$false;try{Assert-PfMvp10Preflight $badFile $incomplete 'runtime-preflight'|Out-Null}catch{$failed=$_.Exception.Message -match 'inventory'};if(-not $failed -or $spy.Invocations.Count -ne $before){throw 'incomplete inventory reached executor'};$passed++
 $cancelAuthorization=New-Authorization (Join-Path $scratch 'cancel-evidence');New-Item -ItemType Directory -Path $cancelAuthorization.evidenceDirectory|Out-Null;Set-Content -LiteralPath (Join-Path $cancelAuthorization.evidenceDirectory 'CANCEL') -Value 'cancel';$cancelFile=Save-Authorization $cancelAuthorization 'cancel';$before=$spy.Invocations.Count;$failed=$false;try{Assert-PfMvp10Preflight $cancelFile $inventoryPath 'runtime-preflight'|Out-Null}catch{$failed=$_.Exception.Message -match 'cancellation'};if(-not $failed -or $spy.Invocations.Count -ne $before){throw 'cancelled preflight reached executor'};$passed++
 $failureAuthorization=New-Authorization (Join-Path $scratch 'failure-evidence');$failureFile=Save-Authorization $failureAuthorization 'failure';Enqueue-Frame $spy 'PF_PASS|runtime|170000|target-verified';Enqueue-Frame $spy 'PF_PASS|package-state|000039';$spy.Results.Enqueue((New-ProcessResult '' '{"password":"hunter2","nested":{"token":"abc"},"items":[{"secret":"value"}]}' 1));$preflight=Assert-PfMvp10Preflight $failureFile $inventoryPath 'fixture-cleanup';$failed=$false;try{Invoke-PfMvp10Command -Preflight $preflight -Command 'fixture-cleanup'|Out-Null}catch{$failed=$_.Exception.Message -match 'diagnostic content discarded'};if(-not $failed){throw 'ownership failure was not propagated'};$retained=(Get-Content -Raw -LiteralPath (Join-Path $failureAuthorization.evidenceDirectory 'fixture-cleanup/90_cleanup.sql.err'));if($retained -match 'hunter2|abc|value|password|token|secret'){throw 'nested diagnostic entered retained evidence'};$passed++
 $diagnosticBase=Join-Path $scratch 'diagnostic';$approvedDiagnosticSource=Join-Path $PSScriptRoot 'sql/00_runtime_compatibility.sql';foreach($payload in @('{"quoted key":"secret-value","nested":{"password":"x"},"array":["token-value"]}','ordinary password=hunter2 text','NOTICE: {"token":"abc"}')){$failed=$false;try{Complete-PfMvp10ProcessEvidence (New-ProcessResult $payload $payload 0) '^PF_PASS\|never$' $diagnosticBase $approvedDiagnosticSource|Out-Null}catch{$failed=$true};if(-not $failed){throw 'unsafe diagnostic accepted'};$retained=(Get-Content -Raw ($diagnosticBase+'.out'))+(Get-Content -Raw ($diagnosticBase+'.err'));if($retained -match 'secret-value|password|token-value|hunter2|abc|quoted key'){throw 'unsafe diagnostic retained'}};$passed++
 if((Get-Content -Raw -LiteralPath (Join-Path $authorization.evidenceDirectory 'fixture-cleanup/90_cleanup.sql.out')).Trim() -cne 'PF_RESULT|cleanup|REFUSED|immutable-evidence-preserved'){throw 'cleanup refusal evidence absent'};$passed++
 if((Get-Content -Raw -LiteralPath (Join-Path $authorization.evidenceDirectory 'concurrency/summary.json')) -notmatch 'EXECUTED_UNREVIEWED'){throw 'successful structured concurrency summary absent'};$passed++
 Write-Output "PF-MVP-10 whole-command surface rehearsal: $passed passed"
}finally{[PfProcessBridge]::Reset();Remove-Item -LiteralPath $scratch -Recurse -Force}
